{
    const path = newSketchOnPlane(context, id + "path", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(path, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skLineSegment(path, "l2", { "start" : vector(100, 0) * millimeter, "end" : vector(100, 60) * millimeter });
    skSolve(path);
    frame(context, id + "frame1", { "selections" : qOwnedByBody(qBodyType(qCreatedBy(id + "path", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "profileSketch" : profileOf(squareTube), "cornerOverrides" : [{ "vertex" : qContainsPoint(qOwnedByBody(qCreatedBy(id + "path", EntityType.BODY), EntityType.VERTEX), vector(100, 0, 0) * millimeter), "cornerType" : FrameCornerType.BUTT, "cornerButtFlip" : false }] });
}

